UPDATE member2 SET email = #{email}, birth = TO_DATE(#{birth},'YYYY-MM-DD'), 
	tel = #{tel, jdbcType=VARCHAR}, 
	profile_photo = #{profile_photo, jdbcType=VARCHAR}, 
	zip = #{zip, jdbcType=VARCHAR}, addr1 = #{addr1, jdbcType=VARCHAR}, 
	addr2 = #{addr2, jdbcType=VARCHAR}, gender = #{gender}, pref_position = #{pref_position}
WHERE memberIdx = #{memberIdx}
